import { createHash } from "node:crypto";
import { lstat, readdir, readFile, readlink, writeFile } from "node:fs/promises";
import { isAbsolute, join, relative, resolve, sep } from "node:path";

export const runtimePackages = new Map([
  ["@anthropic-ai/tokenizer", "0.0.4"], ["tiktoken", "1.0.22"],
  ["@types/node", "18.19.130"], ["undici-types", "5.26.5"],
]);
export const sha256 = (data) => createHash("sha256").update(data).digest("hex");
export const json = async (path) => JSON.parse(await readFile(path, "utf8"));
export const writeJson = (path, value, options = {}) => writeFile(path, JSON.stringify(value, null, 2) + "\n", options);
export function within(root, path) {
  const rel = relative(resolve(root), resolve(path));
  if (rel === ".." || rel.startsWith(".." + sep) || isAbsolute(rel)) throw new Error("path escapes module: " + path);
  return rel.split(sep).join("/");
}
export async function inventory(root) {
  const files = [];
  async function visit(directory) {
    for (const name of (await readdir(directory)).sort()) {
      const path = join(directory, name), stat = await lstat(path);
      const item = { path: within(root, path) };
      if (stat.isDirectory()) await visit(path);
      else if (stat.isSymbolicLink()) files.push({ ...item, type: "symlink", target: await readlink(path) });
      else if (stat.isFile()) {
        const data = await readFile(path);
        files.push({ ...item, type: "file", bytes: data.length, sha256: sha256(data) });
      } else throw new Error("unsupported file kind: " + path);
    }
  }
  await visit(root);
  return { schema: 1, bytes: files.reduce((total, file) => total + (file.bytes ?? 0), 0),
    regularFiles: files.filter((file) => file.type === "file").length, files };
}
export async function installedPackages(root) {
  const packages = [];
  async function visit(directory, prefix) {
    for (const entry of (await readdir(directory, { withFileTypes: true })).sort((a, b) => a.name.localeCompare(b.name))) {
      if (entry.name.startsWith(".")) continue;
      const path = join(directory, entry.name), key = prefix + entry.name;
      if (!entry.isDirectory()) throw new Error("unexpected package entry: " + key);
      if (entry.name.startsWith("@")) { await visit(path, key + "/"); continue; }
      const manifest = await json(join(path, "package.json"));
      packages.push({ path: key, name: manifest.name, version: manifest.version });
      try { await visit(join(path, "node_modules"), key + "/node_modules/"); }
      catch (error) { if (error.code !== "ENOENT") throw error; }
    }
  }
  await visit(join(root, "node_modules"), "node_modules/");
  return packages.sort((a, b) => a.path.localeCompare(b.path));
}
export async function verifyRuntime(root) {
  const actual = await installedPackages(root);
  const expected = [...runtimePackages].map(([name, version]) => ({ path: "node_modules/" + name, name, version }))
    .sort((a, b) => a.path.localeCompare(b.path));
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error("runtime package graph is not the pinned four-package closure");
  return actual;
}
export function verifyRetainedFiles(before, after) {
  const prefixes = [...runtimePackages.keys()].map((name) => "node_modules/" + name + "/");
  const retained = (report) => report.files.filter((file) => prefixes.some((prefix) => file.path.startsWith(prefix)));
  if (JSON.stringify(retained(before)) !== JSON.stringify(retained(after))) {
    throw new Error("retained package contents changed, were added, or were deleted");
  }
}

import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { once } from "node:events";
import { mkdtemp, rm } from "node:fs/promises";
import { createRequire } from "node:module";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createInterface } from "node:readline";
import { fileURLToPath } from "node:url";
import { randomUUID } from "node:crypto";

assert.equal(Number(process.versions.node.split(".")[0]), 22, "this packaging gate requires Node.js 22");
assert.ok(!process.env.NODE_PATH && !process.env.NODE_OPTIONS, "run with NODE_PATH and NODE_OPTIONS removed");
const root = fileURLToPath(new URL("../", import.meta.url));
const require = createRequire(new URL("../package.json", import.meta.url));
const tokenizer = require("@anthropic-ai/tokenizer");
const fixtures = ["", "x", "The quick brown fox jumps over the lazy dog.", "Привет 世界 café e\u0301 \uFB01", "<|endoftext|> <protect>KEEP</protect>"];
// Direct API has no DCP fallback: a missing WASM file must throw.
const tokenCounts = fixtures.map((text) => tokenizer.countTokens(text));
assert.equal(tokenCounts[0], 0);
assert.ok(tokenCounts.every((count) => Number.isInteger(count) && count >= 0));
assert.ok(tokenCounts[1] > 0, "'x' must not use DCP's length/4 fallback (which returns zero)");
for (let i = 0; i < fixtures.length; i++) {
  const encoder = tokenizer.getTokenizer();
  try { assert.equal(encoder.encode(fixtures[i].normalize("NFKC"), "all").length, tokenCounts[i]); }
  finally { encoder.free(); }
}
const directory = await mkdtemp(join(tmpdir(), "proteus-dcp-relocated-probe-"));
const child = spawn(process.execPath, ["--no-global-search-paths", join(root, "dist/worker.js")],
  { cwd: directory, env: { ...process.env, HOME: directory, XDG_DATA_HOME: join(directory, "data") } });
const closed = once(child, "close");
const lines = createInterface({ input: child.stdout });
let errors = "";
child.stderr.setEncoding("utf8").on("data", (data) => { errors += data; });
const pending = new Map();
let protocolError;
const fail = (error) => {
  protocolError = error;
  for (const waiter of pending.values()) waiter.reject(error);
  pending.clear();
};
child.once("error", fail);
child.once("exit", () => { if (pending.size) fail(new Error("worker exited: " + errors)); });
lines.on("line", (line) => {
  try {
    const frame = JSON.parse(line);
    assert.equal(frame.jsonrpc, "2.0");
    assert.ok(!frame.method, "this probe must not issue host callbacks");
    const waiter = pending.get(frame.id);
    assert.ok(waiter, "unexpected worker response");
    pending.delete(frame.id);
    if (frame.error) waiter.reject(new Error(JSON.stringify(frame.error)));
    else waiter.resolve(frame.result);
  } catch (error) { fail(error); }
});
const send = (id, method, params) => new Promise((resolve, reject) => {
  if (protocolError) return reject(protocolError);
  const timeout = setTimeout(() => { pending.delete(id); reject(new Error("worker timeout: " + errors)); }, 8000);
  pending.set(id, { resolve: (value) => { clearTimeout(timeout); resolve(value); },
    reject: (error) => { clearTimeout(timeout); reject(error); } });
  child.stdin.write(JSON.stringify({ jsonrpc: "2.0", id, method, params }) + "\n");
});
const envelope = (id, slot, module_id, params) => ({ export: { slot, module_id },
  lineage: { root_invocation_id: id, parent_invocation_id: null, depth: 0 }, params });
let probeResult, exitStatus;
let shutdownTimedOut = false;
try {
  const binding = (slot, module_id) => ({ slot, module_id, contract_version: "v6", composition: "ordered_many",
    module_config: { state_dir: join(directory, "state") }, host_features: [] });
  const initialized = await send("h:1:0", "initialize", { protocol_version: "v3", component_id: "dcp",
    exports: [binding("hook", "hook.dcp"), binding("tool", "dcp.tools")] });
  assert.equal(initialized.exports.length, 2);
  const listed = (await send("h:1:1", "list", envelope("h:1:1", "tool", "dcp.tools", null))).result;
  assert.deepEqual(listed.map((tool) => tool.spec.name), ["compress", "dcp"]);
  const messages = [{ id: randomUUID(), role: "User", phase: null, name: null, tool_call_id: null, metadata: {},
    parts: [{ part_id: randomUUID(), provenance: "model", scope: "conversation", payload: { Text: { text: "x" } } }] }];
  const outcome = (await send("h:1:2", "hook.invoke", envelope("h:1:2", "hook", "hook.dcp", {
    cwd: directory, attribution: { execution_id: randomUUID(), agent: { session_id: randomUUID(), thread_id: randomUUID(), turn_id: randomUUID() } },
    conversation: { messages, model_context: [] }, event: { event: "before_model", origin: "direct",
      request: { model: { provider: "fake", model: "fake" }, messages, tools: [listed[0].spec],
        instructions: [{ kind: "System", text: "x", priority: 100 }], limits: { max_input_tokens: 128000, max_output_tokens: null } } },
  }))).result;
  assert.equal(outcome.action, "model_context");
  assert.ok(outcome.messages.length > 0);
  if (protocolError) throw protocolError;
  probeResult = { nodeMajor: 22, tokenCounts, exports: ["hook.dcp", "dcp.tools"], hookAction: outcome.action };
} finally {
  child.stdin.end();
  const timer = setTimeout(() => { shutdownTimedOut = true; child.kill("SIGKILL"); }, 1000);
  try { exitStatus = await closed; }
  finally {
    clearTimeout(timer);
    lines.close();
    await rm(directory, { recursive: true, force: true });
  }
}
assert.equal(shutdownTimedOut, false, "worker exceeded shutdown deadline");
assert.deepEqual(exitStatus, [0, null], "worker must exit cleanly: " + errors);
if (protocolError) throw protocolError;
console.log(JSON.stringify(probeResult));

import { cp, mkdir, readdir, readFile, copyFile, rm } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { builtinModules } from "node:module";
import { inventory, json, sha256, within, writeJson } from "./common.mjs";

const builtin = new Set(builtinModules.flatMap((name) => [name, "node:" + name]));
const legalFile = /^(licen[cs]e|notice|copying|copyright)([._-]|$)/i;
export async function preserveBuild(metafile) {
  const root = process.cwd(), destination = resolve("dist/provenance");
  const lockBytes = await readFile("package-lock.json");
  const lock = JSON.parse(lockBytes), packages = new Map();
  const externals = [...new Set(Object.values(metafile.outputs).flatMap((output) =>
    output.imports.filter((entry) => entry.external).map((entry) => entry.path)))].sort();
  const npmExternals = externals.filter((name) => !builtin.has(name));
  if (JSON.stringify(npmExternals) !== JSON.stringify(["@anthropic-ai/tokenizer"])) {
    throw new Error("unexpected runtime external set: " + JSON.stringify(npmExternals));
  }
  // This is generated build output only. Never prune the developer's install.
  await rm(destination, { recursive: true, force: true });
  await mkdir(destination, { recursive: true });
  await writeJson(join(destination, "esbuild-metafile.json"), metafile);
  for (const path of Object.keys(metafile.inputs).sort()) {
    within(root, path);
    if (path.startsWith("<")) throw new Error("unrecorded virtual build input: " + path);
    const source = resolve(path), target = join(destination, "inputs", path);
    await mkdir(dirname(target), { recursive: true });
    await copyFile(source, target);
    if (!path.startsWith("node_modules/")) continue;
    const marker = path.lastIndexOf("node_modules/");
    const tail = path.slice(marker + "node_modules/".length).split("/");
    const key = path.slice(0, marker) + "node_modules/" + tail.slice(0, tail[0].startsWith("@") ? 2 : 1).join("/");
    if (!lock.packages[key]) throw new Error("input missing from lock: " + path);
    const entry = packages.get(key) ?? { path: key, ...lock.packages[key], inputs: [], emittedBytes: 0 };
    entry.inputs.push(path);
    entry.emittedBytes += Object.values(metafile.outputs).reduce((sum, output) => sum + (output.inputs[path]?.bytesInOutput ?? 0), 0);
    packages.set(key, entry);
  }
  for (const [key, entry] of packages) {
    const target = join(destination, "package-notices", key);
    await mkdir(target, { recursive: true });
    await copyFile(join(key, "package.json"), join(target, "package.json"));
    entry.legalFiles = [];
    for (const file of await readdir(key, { withFileTypes: true })) {
      if (file.isFile() && legalFile.test(file.name)) {
        await copyFile(join(key, file.name), join(target, file.name));
        entry.legalFiles.push(file.name);
      }
    }
    if (entry.legalFiles.length === 0 && key === "node_modules/@opencode-ai/plugin" && entry.version === "1.18.35") {
      // The locked npm tarball omits legal files. Preserve the official release license explicitly.
      const legal = await readFile("packaging/licenses/opencode-1.18.35.LICENSE");
      const digest = "625f0f619133f89bbbb2abe37369613dfa1885eba1e50d02170deb62bb42cb6b";
      if (sha256(legal) !== digest) throw new Error("pinned plugin license changed");
      await copyFile("packaging/licenses/opencode-1.18.35.LICENSE", join(target, "LICENSE.upstream"));
      entry.legalFiles.push("LICENSE.upstream");
      entry.licenseProvenance = {
        source: "https://github.com/anomalyco/opencode/blob/53d1eabb61e21162157817bf677da0a4ad3332e3/LICENSE",
        gitBlob: "6439474beed8e0271df9862eff97ffd70ec2464c", sha256: digest,
        note: "The npm tarball omits a license. This is the official v1.18.35 release license, not a claim of npm gitHead equivalence.",
      };
    }
    entry.legalFiles.sort();
    if (entry.legalFiles.length === 0) throw new Error("no package license/notice found: " + key);
  }
  // Preserve all published upstream sources, not just tree-shaken inputs.
  await cp("node_modules/@tarquinen/opencode-dcp", join(destination, "upstream/opencode-dcp"),
    { recursive: true, dereference: false, verbatimSymlinks: true });
  await copyFile("package-lock.json", join(destination, "build-package-lock.json"));
  await copyFile("package.json", join(destination, "build-package.json"));
  await copyFile("build.mjs", join(destination, "build.mjs"));
  await writeJson(join(destination, "embedded-packages.json"), {
    schema: 1,
    sourceRevision: "Proteus-harness/Proteus-modules@0d9c5fd18f04e6e3a083351678065c5f72966792",
    sourceRevisionNote: "Base revision; the complete applied packaging changes are shipped beside this provenance.",
    build: { node: process.version, esbuild: (await json("node_modules/esbuild/package.json")).version,
      packageLockSha256: sha256(lockBytes) },
    upstream: { name: "@tarquinen/opencode-dcp", version: "3.2.0",
      verifiedLibRevision: "f8232fde1e63c2251687e4d9634bd53ce11568cb",
      note: "The published lib/ matches this revision; this is not an assertion about npm gitHead." },
    externals, packages: [...packages.values()].sort((a, b) => a.path.localeCompare(b.path)),
    securityNote: "Packaging only. Embedded Zod 4.1.8 remains; pruning node_modules is not remediation.",
  });
  const sourceInventory = await inventory(destination);
  await writeJson(join(destination, "source-inventory.json"), sourceInventory);
}

import { cp, mkdir, readFile, access, realpath } from "node:fs/promises";
import { execFileSync } from "node:child_process";
import { basename, dirname, isAbsolute, join, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";
import { inventory, runtimePackages, verifyRetainedFiles, verifyRuntime, writeJson } from "./common.mjs";

const source = await realpath(fileURLToPath(new URL("../", import.meta.url)));
const destination = process.argv[2];
if (process.argv.length !== 3 || !destination || !isAbsolute(destination)) {
  throw new Error("usage: npm run package:runtime -- /absolute/new/staging-directory");
}
const requested = resolve(destination);
const target = join(await realpath(dirname(requested)), basename(requested));
const overlaps = (a, b) => { const rel = relative(a, b); return rel === "" || (rel !== ".." && !rel.startsWith(".." + sep) && !isAbsolute(rel)); };
if (overlaps(source, target) || overlaps(target, source)) throw new Error("staging and source must not overlap");
await access(join(source, "dist/provenance/embedded-packages.json"));
await mkdir(target); // Exclusive: a previous or partially built stage is never overwritten.
for (const item of ["src", "dist", "packaging", "tests", "README.md", "build.mjs", "package.json", "package-lock.json", "node_modules"]) {
  await cp(join(source, item), join(target, item), { recursive: true, dereference: false, verbatimSymlinks: true });
}
const prefix = join(dirname(target), basename(target));
const before = await inventory(target), fullLock = await readFile(join(target, "package-lock.json"));
await writeJson(prefix + ".before-prune.json", before, { flag: "wx" });
execFileSync(process.platform === "win32" ? "npm.cmd" : "npm",
  ["prune", "--omit=dev", "--ignore-scripts", "--no-audit", "--no-fund", "--offline"],
  { cwd: target, stdio: "inherit", env: { ...process.env, npm_config_audit: "false", npm_config_fund: "false" } });
await verifyRuntime(target);
const after = await inventory(target);
const allowed = [...runtimePackages.keys()].map((name) => "node_modules/" + name + "/");
for (const file of after.files.filter((entry) => entry.path.startsWith("node_modules/"))) {
  if (file.path !== "node_modules/.package-lock.json" && !allowed.some((prefix) => file.path.startsWith(prefix))) {
    throw new Error("unexpected runtime dependency file: " + file.path);
  }
}
verifyRetainedFiles(before, after);
if (!fullLock.equals(await readFile(join(target, "package-lock.json")))) {
  throw new Error("npm normalized the full build lock; review and regenerate the candidate lock before packaging");
}
await writeJson(prefix + ".after-prune.json", after, { flag: "wx" });
await writeJson(prefix + ".prune-summary.json", {
  schema: 1, candidateBeforePruneBytes: before.bytes, candidateAfterPruneBytes: after.bytes,
  prunedBytes: before.bytes - after.bytes,
  caveat: "Prune delta, not net shipping savings. Compare the final inventory with an independently rebuilt unmodified baseline, including newly retained source and metadata.",
  runtimePackages: await verifyRuntime(target),
}, { flag: "wx" });
console.log("Created runtime stage: " + target);

import assert from "node:assert/strict";
import { mkdtemp, mkdir, rm, symlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { inventory, runtimePackages, verifyRetainedFiles, verifyRuntime, within } from "../packaging/common.mjs";

async function temporary(t) {
  const directory = await mkdtemp(join(tmpdir(), "proteus-dcp-package-test-"));
  t.after(() => rm(directory, { recursive: true, force: true }));
  return directory;
}
test("inventory records exact contents and symlink destinations without following links", async (t) => {
  const directory = await temporary(t);
  await writeFile(join(directory, "b"), "two");
  await writeFile(join(directory, "a"), "one");
  await symlink("a", join(directory, "c"));
  const first = await inventory(directory), second = await inventory(directory);
  assert.deepEqual(first, second);
  assert.equal(first.bytes, 6);
  assert.equal(first.regularFiles, 2);
  assert.deepEqual(first.files.map((entry) => entry.path), ["a", "b", "c"]);
  assert.deepEqual(first.files[2], { path: "c", type: "symlink", target: "a" });
  await writeFile(join(directory, "a"), "ONE");
  const changed = await inventory(directory);
  assert.notEqual(changed.files[0].sha256, first.files[0].sha256);
  assert.equal(changed.files[1].sha256, first.files[1].sha256);
});
test("runtime closure accepts the complete four packages and rejects added or changed packages", async (t) => {
  const directory = await temporary(t);
  const put = async (name, version) => {
    const path = join(directory, "node_modules", name);
    await mkdir(path, { recursive: true });
    await writeFile(join(path, "package.json"), JSON.stringify({ name, version }));
  };
  for (const [name, version] of runtimePackages) await put(name, version);
  assert.equal((await verifyRuntime(directory)).length, 4);
  await put("zod", "4.1.8");
  await assert.rejects(verifyRuntime(directory), /four-package closure/);
  await rm(join(directory, "node_modules/zod"), { recursive: true });
  await put("tiktoken", "9.9.9");
  await assert.rejects(verifyRuntime(directory), /four-package closure/);
});
test("artifact path mapping rejects parent traversal", () => {
  assert.equal(within("/module", "/module/src/worker.mjs"), "src/worker.mjs");
  assert.throws(() => within("/module", "/other/source"), /escapes module/);
});

test("retained package proof rejects deletions, additions, edits, and symlink changes", () => {
  const file = { path: "node_modules/tiktoken/lite/tiktoken_bg.wasm", type: "file", bytes: 3, sha256: "abc" };
  const link = { path: "node_modules/tiktoken/example-link", type: "symlink", target: "lite/tiktoken_bg.wasm" };
  const before = { files: [file, link] };
  verifyRetainedFiles(before, structuredClone(before));
  assert.throws(() => verifyRetainedFiles(before, { files: [link] }), /deleted/);
  assert.throws(() => verifyRetainedFiles(before, { files: [file, link, { ...file, path: file.path + ".extra" }] }), /added/);
  assert.throws(() => verifyRetainedFiles(before, { files: [{ ...file, sha256: "changed" }, link] }), /changed/);
  assert.throws(() => verifyRetainedFiles(before, { files: [file, { ...link, target: "other.wasm" }] }), /changed/);
});
